-- 10-reference-links.sql
-- Source: NIST_SP-800-53_rev5_catalog-min.json @ oscal-content 78650f02ad93; live results of 2026-09-30
-- 836 reference links on 219 live controls, from 158 of 201 back-matter resources; live check of 2026-09-30

-- Source: the back-matter resources of the catalog, joined to the reference links of each control.
-- Each URL is the most current known location of the resource: 134 rows carry a URL other
-- than the one the catalog publishes, because the published one redirects or is gone and a
-- replacement was verified (sources/reference-links/nist-800-53/overrides.csv). The provenance of every row, the
-- published URL, the live-check outcome and what was needed for the URL to be accurate, is in
-- reports/reference-links/nist-800-53/registry.csv; the redirect report for the publisher is beside it.
-- Not seeded: 3 resources whose published URL is gone with no replacement known.
-- Flagged for a manual check: 20 resources whose host refuses scripted clients or serves an incomplete certificate chain.
-- The description column carries the citation text from the catalog; resolvedUrl and contentType say what the link leads to.
-- The DataSource row records the retrieval; every link row points at it.
VALUES ('dsrc_reference-links_nist-800-53', 'nist-800-53 reference links', 'reference-links', 'https://github.com/usnistgov/oscal-content/tree/78650f02ad9321bb7b817846f8fbd4f2bcd620de/nist.gov/SP800-53/rev5/json', 'reference'::"AuthorityLevel", '2026-09-30'::timestamp, true, 'Reference links from the back-matter of NIST SP 800-53 Rev 5 (catalog version 5.2.0) at oscal-content 78650f02ad93: 201 resources, 158 seeded, 3 held out, 20 flagged for a manual check; live check of 2026-09-30.', 'system_nist_gov', NOW(), NOW())
ON CONFLICT ("id") DO UPDATE SET "url" = EXCLUDED."url", "lastCrawled" = EXCLUDED."lastCrawled", "description" = EXCLUDED."description", "updatedAt" = NOW();

ON CONFLICT ("id") DO NOTHING;
